3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
8	
9	/**
10	 * Rejects a create-owner request whose email is already used by another owner, responding
11	 * 409. Runs after {@link NormalizeOwnerEmail}, so the request's email is already trimmed
12	 * and lower-cased (or absent). An absent email cannot collide, so the step is a no-op;
13	 * otherwise the normalized request email is compared against every existing owner's email
14	 * normalized the same way (see {@link OwnerEmails}), so the match is case-insensitive.
15	 */
16	public class RejectDuplicateOwnerEmail {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateEmailException {
20	        String email = request.getEmail();
21	        if (!OwnerEmails.isPresent(email)) {
22	            return;
23	        }
24	        for (Owner existing : ownerRepository.findAll()) {
25	            String existingEmail = existing.getEmail();
26	            if (OwnerEmails.isPresent(existingEmail)
27	                    && email.equals(OwnerEmails.normalize(existingEmail))) {
28	                throw new DuplicateEmailException(email);
29	            }
30	        }
31	    }
32	}
