19	            return;
20	        }
21	        if (!OwnerHouseholds.members(ownerRepository.findAll(),
22	                request.getLastName(), request.getAddress()).isEmpty()) {
23	            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
