1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * The single rule set for owner email addresses: what counts as "present", what counts as
8	 * a syntactically valid address, and how one is normalized for storage. Shared so every step
9	 * that touches an owner email treats it the same way.
10	 */
11	final class OwnerEmails {
12	
13	    /** local-part {@code @} domain, no whitespace, and a dotted domain. */
14	    private static final Pattern SYNTAX = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
15	
16	    private OwnerEmails() {
17	    }
18	
19	    /** An email is present when it is non-null and not blank; blank is treated as omitted. */
20	    static boolean isPresent(String email) {
21	        return email != null && !email.isBlank();
22	    }
23	
24	    /** Whether {@code email} is a syntactically valid address. */
25	    static boolean isValid(String email) {
26	        return email != null && SYNTAX.matcher(email).matches();
27	    }
28	
29	    /** The stored form of an email: trimmed and lower-cased. */
30	    static String normalize(String email) {
31	        return email.trim().toLowerCase(Locale.ROOT);
32	    }
33	}
34

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * The single normalization rule for owner telephones: convert a raw telephone to E.164
10	 * form. Spaces, dashes and brackets are stripped; a leading {@code +} with its country
11	 * code is kept, otherwise country code {@code +61} is assumed and a single leading
12	 * {@code 0} is dropped from the national digits. The result must carry 8 to 15 digits
13	 * after the {@code +}, and — for a recognised country code — exactly the national-number
14	 * length that country requires ({@code +61} → 9 national digits, {@code +1} → 10). Shared
15	 * by {@link NormalizeOwnerTelephone} (which stores the E.164 value on the request) so
16	 * every telephone is stored and compared the same way.
17	 */
18	final class OwnerTelephones {
19	
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	    private static final int MIN_DIGITS = 8;
22	    private static final int MAX_DIGITS = 15;
23	
24	    /**
25	     * Country calling code → required national-number length. Ordered longest code first
26	     * so {@link #nationalLength} matches the most specific calling code (e.g. {@code 61}
27	     * before {@code 1}).
28	     */
29	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
30	
31	    static {
32	        NATIONAL_LENGTHS.put("61", 9);
33	        NATIONAL_LENGTHS.put("1", 10);
34	    }
35	
36	    private OwnerTelephones() {
37	    }
38	
39	    /**
40	     * The E.164 form of {@code telephone} (a leading {@code +} followed by 8 to 15 digits).
41	     *
42	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
43	     */
44	    static String toE164(String telephone) throws InvalidTelephoneException {
45	        String cleaned = (telephone == null ? "" : telephone).replaceAll("[\\s()-]", "");
46	
47	        String digits;
48	        if (cleaned.startsWith("+")) {
49	            digits = cleaned.substring(1);
50	        } else {
51	            digits = dropSingleLeadingZero(cleaned);
52	            digits = DEFAULT_COUNTRY_CODE + digits;
53	        }
54	
55	        if (!digits.matches("\\d+") || digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
56	            throw new InvalidTelephoneException(
57	                    "Telephone must form a valid E.164 number with " + MIN_DIGITS + " to " + MAX_DIGITS
58	                            + " digits after the country code");
59	        }
60	        requireCountryNationalLength(digits);
61	        return "+" + digits;
62	    }
63	
64	    /**
65	     * For a recognised country calling code, rejects a number whose national part is not the
66	     * exact length that country requires. Unrecognised codes keep the generic length check only.
67	     */
68	    private static void requireCountryNationalLength(String digits) throws InvalidTelephoneException {
69	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
70	            String code = country.getKey();
71	            if (digits.startsWith(code)) {
72	                int nationalLength = digits.length() - code.length();
73	                int required = country.getValue();
74	                if (nationalLength != required) {
75	                    throw new InvalidTelephoneException("Telephone with country code +" + code
76	                            + " must have " + required + " national digits, but has " + nationalLength);
77	                }
78	                return;
79	            }
80	        }
81	    }
82	
83	    private static String dropSingleLeadingZero(String digits) {
84	        return digits.startsWith("0") ? digits.substring(1) : digits;
85	    }
86	}
87

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * The single normalization rule for owner addresses: trim, collapse runs of whitespace to a
8	 * single space, upper-case, and expand common street-type abbreviations (ST->STREET, RD->ROAD,
9	 * AVE->AVENUE). Shared by {@link NormalizeOwnerAddress} (which stores the normalized value on the
10	 * request) so every address is stored, returned and compared — duplicate-household detection and
11	 * the shared household id (see {@link OwnerHouseholds}) — in the same form.
12	 */
13	final class OwnerAddresses {
14	
15	    /** Upper-cased abbreviation -> its expansion, matched a whole word at a time. */
16	    private static final Map<String, String> ABBREVIATIONS = Map.of(
17	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
18	
19	    private OwnerAddresses() {
20	    }
21	
22	    /**
23	     * The stored form of an address: trimmed, internal whitespace collapsed, upper-cased and with
24	     * common street-type abbreviations expanded. A {@code null} or blank input normalizes to the
25	     * empty string.
26	     */
27	    static String normalize(String address) {
28	        if (address == null || address.isBlank()) {
29	            return "";
30	        }
31	        String[] words = address.trim().toUpperCase(Locale.ROOT).split("\\s+");
32	        StringBuilder normalized = new StringBuilder(address.length());
33	        for (String word : words) {
34	            if (normalized.length() > 0) {
35	                normalized.append(' ');
36	            }
37	            normalized.append(ABBREVIATIONS.getOrDefault(word, word));
38	        }
39	        return normalized.toString();
40	    }
41	}
