15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    Owner toOwner(OwnerDto ownerDto);
31	
32	    /** Format an owner's name as 'LastName, FirstName' for display. */
33	    default String displayName(Owner owner) {
34	        return owner.getLastName() + ", " + owner.getFirstName();
35	    }
36	
37	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
38	    default String initials(Owner owner) {
39	        return initial(owner.getFirstName()) + initial(owner.getLastName());
40	    }
41	
42	    private static String initial(String name) {
43	        return Character.toUpperCase(name.charAt(0)) + ".";
44	    }
45	
46	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
47	     * last two digits of the registrationDate year. */
48	    default String membershipNumber(Owner owner) {
49	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
50	            return null;
51	        }
52	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
53	    }
54	
55	    /** The owner's membership level from 1 to 3: starts at 1, plus 1 when an email is present,
56	     * plus 1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
57	    default int membershipLevel(Owner owner) {
58	        int level = 1;
59	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
60	        if (hasEmail) {
61	            level++;
62	        }
63	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
64	            level++;
65	        }
66	        return Math.min(level, 3);
67	    }
68	
69	    /** The owner's canonical region, derived from the city via the pinned city-to-region table,
70	     * or 'UNKNOWN' when the city is not in the table. */
71	    default String locality(Owner owner) {
72	        return Locality.regionFor(owner.getCity());
73	    }
74	
75	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
76	    default String contactPreference(Owner owner) {
77	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
78	        return hasEmail ? "EMAIL" : "PHONE";
79	    }
80	
81	    @Mapping(target = "id", ignore = true)
82	    @Mapping(target = "pets", ignore = true)
83	    @Mapping(target = "customerCode", ignore = true)
84	    @Mapping(target = "householdId", ignore = true)
85	    @Mapping(target = "namesakeCount", ignore = true)
86	    @Mapping(target = "householdSize", ignore = true)
87	    @Mapping(target = "bulkSignupWarning", ignore = true)
88	    Owner toOwner(OwnerFieldsDto ownerDto);
89	
90	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
91	
92	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
93	
94	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
95	        OwnerPageDto ownerPageDto = new OwnerPageDto();
96	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
97	        ownerPageDto.setPage(ownerPage.getNumber());
98	        ownerPageDto.setSize(ownerPage.getSize());
99	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
100	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
101	        return ownerPageDto;
102	    }
