package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of what a "household" is: owners sharing the same last name and
 * address, compared case-insensitively with runs of whitespace collapsed to a single
 * space. Shared by {@link RejectDuplicateOwnerHousehold} (which forbids an unopted
 * duplicate) and {@link AssignOwnerHousehold} (which links opted-in members), so both
 * decide membership identically.
 */
final class OwnerHouseholds {

    private static final int ID_HEX_LENGTH = 12;

    private OwnerHouseholds() {
    }

    /** The existing owners that share the household identified by {@code lastName} and {@code address}. */
    static List<Owner> members(Iterable<Owner> owners, String lastName, String address) {
        String canonicalLastName = canonical(lastName);
        String canonicalAddress = canonical(address);
        List<Owner> members = new ArrayList<>();
        for (Owner existing : owners) {
            if (canonicalLastName.equals(canonical(existing.getLastName()))
                    && canonicalAddress.equals(canonical(existing.getAddress()))) {
                members.add(existing);
            }
        }
        return members;
    }

    /**
     * A stable identifier for the household: derived from the canonical last name and
     * address, so every member computes the same value regardless of creation order.
     */
    static String householdId(String lastName, String address) {
        String key = canonical(lastName) + "�" + canonical(address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(ID_HEX_LENGTH);
            for (int i = 0; hex.length() < ID_HEX_LENGTH; i++) {
                hex.append(String.format("%02X", digest[i] & 0xFF));
            }
            return hex.substring(0, ID_HEX_LENGTH);
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required to derive a household id", ex);
        }
    }

    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
    private static String canonical(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

